from __future__ import annotations
from cadgen import step
from lib.steve_compat import to_build123d


def make():
    import math
    import cadquery as cq
    from lib.steve_compat import Model
    SIDE = 1
    split_z = -12.3857
    axis_x = -42.899
    axis_z = 3.975
    shoulder_r = 21.99
    shoulder_y0 = 44.145
    shoulder_y1 = 90.315
    bed_r = 22.13
    bed_y0 = 45.78
    bed_y1 = 88.68
    plate_x0 = -69.899
    plate_x1 = 3.001
    plate_round_r = 6.75
    tab_x0_a = -65.5
    tab_x0_b = -15.2
    tab_dx = 4.0
    tab_y0 = 60.43
    tab_y1 = 74.03
    tab_h = 8.2
    rocker_tilt = 4.824
    rocker_y = 67.0
    rocker_z = -25.5646
    
    def _p3(axis, lvl, u, v):
        return cq.Vector(*((lvl, u, v) if axis == 0 else (u, lvl, v) if axis == 1 else (u, v, lvl)))
    
    def _edges(ring, at):
        start, segs = ring
        cur = at(*start)
        edges = []
        for s in segs:
            nxt = at(*s[-1])
            if s[0] == 'A' and (at(*s[1]) - cur).cross(nxt - cur).Length > 0.0001:
                edges.append(cq.Edge.makeThreePointArc(cur, at(*s[1]), nxt))
            elif (nxt - cur).Length > 1e-06:
                edges.append(cq.Edge.makeLine(cur, nxt))
            cur = nxt
        return cq.Wire.assembleEdges(edges)
    
    def _face(axis, lvl, outer, holes=()):
        f = cq.Face.makeFromWires(_edges(outer, lambda u, v: _p3(axis, lvl, u, v)), [_edges(h, lambda u, v: _p3(axis, lvl, u, v)) for h in holes])
        return f if f.isValid() else f.fix()
    
    def slab_stack(axis, slabs):
        """Stacked extrusions along one world axis: [[lo, hi, [[outer_ring, [hole_rings]], ...]], ...].
        A ring is [start, segments]; a segment is ["L", end] or ["A", through, end]."""
        out = None
        for lo, hi, faces in slabs:
            d = [0, 0, 0]
            d[axis] = hi - lo
            for outer, holes in faces:
                s = cq.Solid.extrudeLinear(_face(axis, lo, outer, holes), cq.Vector(*d))
                out = s if out is None else out.fuse(s)
        return out.clean()
    
    def side(shape):
        return shape.mirror('XZ') if SIDE < 0 else shape
    
    def cradle_cut():
        shoulder = cq.Solid.makeCylinder(shoulder_r, shoulder_y1 - shoulder_y0, cq.Vector(axis_x, shoulder_y0, axis_z), cq.Vector(0, 1, 0))
        bed = cq.Solid.makeCylinder(bed_r, bed_y1 - bed_y0, cq.Vector(axis_x, bed_y0, axis_z), cq.Vector(0, 1, 0))
        return shoulder.fuse(bed)
    
    def top_envelope():
        c = math.sqrt(0.5) * plate_round_r
        xa, xb = (plate_x0 + plate_round_r, plate_x1 - plate_round_r)
        return cq.Workplane('XZ').moveTo(plate_x0, split_z - 1).lineTo(plate_x1, split_z - 1).lineTo(plate_x1, split_z).threePointArc((xb + c, split_z + c), (xb, split_z + plate_round_r)).lineTo(xb, split_z + 20).lineTo(xa, split_z + 20).lineTo(xa, split_z + plate_round_r).threePointArc((xa - c, split_z + c), (plate_x0, split_z)).close().extrude(-200, both=True).val()
    
    def tab_boxes():
        return cq.Solid.makeBox(tab_dx, tab_y1 - tab_y0, tab_h + 1, cq.Vector(tab_x0_a, tab_y0, split_z - 1)).fuse(cq.Solid.makeBox(tab_dx, tab_y1 - tab_y0, tab_h + 1, cq.Vector(tab_x0_b, tab_y0, split_z - 1)))
    
    def upper_body():
        return slab_stack(2, TOP_SLABS).intersect(top_envelope())
    
    def rocker_limiter():
        yz = None
        for x0, x1, ring in ROCKER_YZ_ZONES:
            p = cq.Solid.extrudeLinear(_face(0, x0, ring), cq.Vector(x1 - x0, 0, 0))
            yz = p if yz is None else yz.fuse(p)
        t = math.radians(rocker_tilt)
        ey = cq.Vector(0, math.cos(t), math.sin(t))
        ez = cq.Vector(0, -math.sin(t), math.cos(t))
        at = lambda u, v: cq.Vector(u, rocker_y, rocker_z) + ez * v - ey * 40
        xz = cq.Solid.extrudeLinear(cq.Face.makeFromWires(_edges(ROCKER_XZ, at)), ey * 80)
        return yz.clean().intersect(xz)
